// SignatureHeader returns the Tally-Signature header of a delivery sent at t: "t=<unix seconds>" and a "v1=<signature>" for
// each secret, current first. The signature covers "<t>.<body>".
func SignatureHeader(secrets []string, t time.Time, body []byte) string {
	ts := strconv.FormatInt(t.Unix(), 10)
	var b strings.Builder
	b.WriteString("t=" + ts)
	for _, secret := range secrets {
		b.WriteString(",v1=" + signTimestamped(secret, ts, body))
	}
	return b.String()
}

// signTimestamped returns the hex HMAC-SHA256 of "<ts>.<payload>", keyed with secret.
func signTimestamped(secret, ts string, payload []byte) string {
	m := hmac.New(sha256.New, []byte(secret))
	m.Write([]byte(ts + "."))
	m.Write(payload)
	return hex.EncodeToString(m.Sum(nil))
}

// Verify checks a Tally-Signature header against a payload. It returns nil when the header's timestamp is within tolerance of
// now and one of its v1 signatures matches the payload signed with one of secrets. A tolerance of 0 means 5 minutes.
func Verify(payload []byte, header string, secrets []string, tolerance time.Duration, now time.Time) error {
	if tolerance == 0 {
		tolerance = defaultTolerance
	}
	if strings.TrimSpace(header) == "" {
		return fmt.Errorf("%w: the header is empty", ErrMalformedHeader)
	}
	var ts string
	var sec int64
	var hasTimestamp bool
	var sigs []string
	for _, pair := range strings.Split(header, ",") {
		key, value, ok := strings.Cut(pair, "=")
		if !ok {
			return fmt.Errorf("%w: %q has no \"=\"", ErrMalformedHeader, strings.TrimSpace(pair))
		}
		key, value = strings.TrimSpace(key), strings.TrimSpace(value)
		switch key {
		case "t":
			n, err := strconv.ParseInt(value, 10, 64)
			if err != nil {
				return fmt.Errorf("%w: t is not an integer", ErrMalformedHeader)
			}
			if !hasTimestamp {
				ts, sec, hasTimestamp = value, n, true
			}
		case "v1":
			sigs = append(sigs, value)
		}
	}
	if !hasTimestamp {
		return ErrNoTimestamp
	}
	if d := now.Sub(time.Unix(sec, 0)); d > tolerance || -d > tolerance {
		return fmt.Errorf("%w: the timestamp is %v from now", ErrTimestampTolerance, d)
	}
	if len(sigs) == 0 {
		return ErrNoSignature
	}
	for _, secret := range secrets {
		want := signTimestamped(secret, ts, payload)
		for _, got := range sigs {
			if hmac.Equal([]byte(got), []byte(want)) {
				return nil
			}
		}
	}
	return ErrSignatureMismatch
}

