func TestSignatureHeader(t *testing.T) {
	now := time.Unix(1700000000, 0)
	body := []byte(`{"id":"evt_1"}`)
	got := webhooks.SignatureHeader([]string{"whsec_new", "whsec_old"}, now, body)
	want := "t=1700000000,v1=" + referenceSignature("whsec_new", 1700000000, body) + ",v1=" + referenceSignature("whsec_old", 1700000000, body)
	if got != want {
		t.Fatalf("SignatureHeader = %s\nwant %s", got, want)
	}
