func TestVerify(t *testing.T) {
	body := []byte(`{"id":"evt_1"}`)
	now := time.Unix(1700000000, 0)
	sig := referenceSignature("whsec_new", 1700000000, body)
	both := webhooks.SignatureHeader([]string{"whsec_new", "whsec_old"}, now, body)
	cases := []struct {
		name    string
		payload []byte
		header  string
		secrets []string
		tol     time.Duration
		at      time.Time
		want    error
	}{
		{name: "valid", payload: body, header: "t=1700000000,v1=" + sig, secrets: []string{"whsec_new"}, at: now},
		{name: "second secret matches", payload: body, header: both, secrets: []string{"whsec_other", "whsec_old"}, at: now},
		{name: "previous entry matches", payload: body, header: both, secrets: []string{"whsec_old"}, at: now},
		{name: "wrong secret", payload: body, header: "t=1700000000,v1=" + sig, secrets: []string{"whsec_wrong"}, at: now, want: webhooks.ErrSignatureMismatch},
		{name: "no secrets", payload: body, header: "t=1700000000,v1=" + sig, at: now, want: webhooks.ErrSignatureMismatch},
		{name: "changed body", payload: []byte(`{"id":"evt_2"}`), header: "t=1700000000,v1=" + sig, secrets: []string{"whsec_new"}, at: now, want: webhooks.ErrSignatureMismatch},
		{name: "timestamp is signed", payload: body, header: "t=1700000001,v1=" + sig, secrets: []string{"whsec_new"}, at: now, want: webhooks.ErrSignatureMismatch},
		{name: "exactly at the default tolerance", payload: body, header: "t=1700000000,v1=" + sig, secrets: []string{"whsec_new"}, at: now.Add(5 * time.Minute), want: nil},
		{name: "too old", payload: body, header: "t=1700000000,v1=" + sig, secrets: []string{"whsec_new"}, at: now.Add(5*time.Minute + time.Second), want: webhooks.ErrTimestampTolerance},
		{name: "too far in the future", payload: body, header: "t=1700000000,v1=" + sig, secrets: []string{"whsec_new"}, at: now.Add(-5*time.Minute - time.Second), want: webhooks.ErrTimestampTolerance},
		{name: "custom tolerance", payload: body, header: "t=1700000000,v1=" + sig, secrets: []string{"whsec_new"}, tol: time.Minute, at: now.Add(2 * time.Minute), want: webhooks.ErrTimestampTolerance},
		{name: "spaces, order and unknown keys", payload: body, header: " v1=" + sig + " , v0=zz , t=1700000000 ", secrets: []string{"whsec_new"}, at: now},
		{name: "empty header", payload: body, header: "", secrets: []string{"whsec_new"}, at: now, want: webhooks.ErrMalformedHeader},
		{name: "pair without =", payload: body, header: "t=1700000000,v1", secrets: []string{"whsec_new"}, at: now, want: webhooks.ErrMalformedHeader},
		{name: "empty pair", payload: body, header: "t=1700000000,,v1=" + sig, secrets: []string{"whsec_new"}, at: now, want: webhooks.ErrMalformedHeader},
		{name: "t not an integer", payload: body, header: "t=yesterday,v1=" + sig, secrets: []string{"whsec_new"}, at: now, want: webhooks.ErrMalformedHeader},
		{name: "empty t", payload: body, header: "t=,v1=" + sig, secrets: []string{"whsec_new"}, at: now, want: webhooks.ErrMalformedHeader},
		{name: "no t", payload: body, header: "v1=" + sig, secrets: []string{"whsec_new"}, at: now, want: webhooks.ErrNoTimestamp},
		{name: "no v1", payload: body, header: "t=1700000000,v0=" + sig, secrets: []string{"whsec_new"}, at: now, want: webhooks.ErrNoSignature},
		{name: "tolerance is checked before signatures", payload: body, header: "t=1700000000", secrets: []string{"whsec_new"}, at: now.Add(time.Hour), want: webhooks.ErrTimestampTolerance},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			err := webhooks.Verify(c.payload, c.header, c.secrets, c.tol, c.at)
			if c.want == nil && err != nil {
