// lastDelivery returns the most recent request the fake receiver got.
func lastDelivery(t *testing.T, e *apitest.Env) apitest.Request {
	t.Helper()
	reqs := e.HTTP.Requests()
	if len(reqs) == 0 {
		t.Fatal("no delivery")
	}
	return reqs[len(reqs)-1]
}

func TestRotatedSecretsSign(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/rotate", Events: []string{"*"}, Secret: "whsec_old", Enabled: true}, e.Clock.Now())
	deliver := func() apitest.Request {
		t.Helper()
		if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
			t.Fatal(err)
		}
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("RunDue = %d, %v", n, err)
		}
		return lastDelivery(t, e)
	}

	if _, err := e.Store.RotateWebhookSecret(e.Acme.ID, ep.ID, "whsec_new", e.Clock.Now().Add(webhooks.SecretOverlap)); err != nil {
		t.Fatal(err)
	}
	req := deliver()
	if h := req.Header.Get("Tally-Signature"); strings.Count(h, ",v1=") != 2 || !strings.HasPrefix(h, "t=") {
		t.Fatalf("after a rotation: Tally-Signature = %s", h)
	}
	h := lastDelivery(t, e).Header.Get("Tally-Signature")
	if err := webhooks.Verify(req.Body, h, []string{"whsec_new"}, 0, e.Clock.Now()); err != nil {
		t.Fatalf("new secret: %v", err)
	}
	if err := webhooks.Verify(req.Body, h, []string{"whsec_old"}, 0, e.Clock.Now()); err != nil {
		t.Fatalf("previous secret: %v", err)
	}

	// Rotating again drops the oldest secret at once.
	if _, err := e.Store.RotateWebhookSecret(e.Acme.ID, ep.ID, "whsec_newer", e.Clock.Now().Add(webhooks.SecretOverlap)); err != nil {
		t.Fatal(err)
	}
	req = deliver()
	h = req.Header.Get("Tally-Signature")
	if strings.Count(h, ",v1=") != 2 {
		t.Fatalf("after a second rotation: Tally-Signature = %s", h)
	}
	if err := webhooks.Verify(req.Body, h, []string{"whsec_old"}, 0, e.Clock.Now()); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Fatalf("dropped secret still signs: %v", err)
	}
	if err := webhooks.Verify(req.Body, h, []string{"whsec_new"}, 0, e.Clock.Now()); err != nil {
		t.Fatalf("previous secret after a second rotation: %v", err)
	}

	// After 24 hours only the current secret signs.
	e.Clock.Advance(webhooks.SecretOverlap)
	req = deliver()
	if h := req.Header.Get("Tally-Signature"); strings.Count(h, ",v1=") != 1 {
		t.Fatalf("after 24 hours: Tally-Signature = %s", h)
	}
	if err := webhooks.Verify(req.Body, req.Header.Get("Tally-Signature"), []string{"whsec_new"}, 0, e.Clock.Now()); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Fatalf("previous secret after 24 hours: %v", err)
	}
	if err := webhooks.Verify(req.Body, req.Header.Get("Tally-Signature"), []string{"whsec_newer"}, 0, e.Clock.Now()); err != nil {
		t.Fatalf("current secret: %v", err)
	}
}
