// referenceSignature is the v1 signature of "<t>.<body>" written out by hand, so the tests do not depend on the code under test.
func referenceSignature(secret string, t int64, body []byte) string {
	m := hmac.New(sha256.New, []byte(secret))
	m.Write([]byte(fmt.Sprintf("%d.", t)))
	m.Write(body)
	return hex.EncodeToString(m.Sum(nil))
}

